import cv2,numpy as np
for vt in [8,12,16,20,25,30,40,50]:
 for lr in [0.0,0.001,0.005,0.01]:
  cap=cv2.VideoCapture('/app/example_video.mp4'); sub=cv2.createBackgroundSubtractorMOG2(history=200,varThreshold=vt,detectShadows=False)
  vals=[]
  for i in range(120):
   ok,f=cap.read();
   if not ok:break
   if lr==0: m=sub.apply(f,learningRate=-1 if i<10 else 0)
   else:m=sub.apply(f,learningRate=-1 if i<10 else lr)
   m[:125]=0;m[410:]=0
   m=cv2.morphologyEx(m,cv2.MORPH_OPEN,np.ones((3,3),np.uint8))
   n,l,st,c=cv2.connectedComponentsWithStats(m)
   cand=[]
   for x,y,w,h,a in st[1:]:
    x,y,w,h,a=map(int,(x,y,w,h,a))
    if a>200 and h>30 and w>10 and y<350 and y+h>180:
     cand.append((a,x,y,w,h))
   cand.sort(reverse=True)
   if cand:
    a,x,y,w,h=cand[0]
    # candidate near center x in likely track region; reject wide full static
    if w<400 and a<30000: vals.append((i,y+h,x+w/2))
    else: vals.append((i,y+h,x+w/2))
   else: vals.append((i,np.nan,np.nan))
  cap.release()
  # find bottom for 47:63
  print('vt',vt,'lr',lr,[(i, None if np.isnan(y) else int(y)) for i,y,x in vals if 49<=i<=63])
